//
// BackendService service processor
//

pub trait BackendServiceSyncHandler {
  fn handle_submit_tasks(&self, tasks: Vec<agent_service::TAgentTaskRequest>) -> thrift::Result<agent_service::TAgentResult>;
  fn handle_make_snapshot(&self, snapshot_request: agent_service::TSnapshotRequest) -> thrift::Result<agent_service::TAgentResult>;
  fn handle_release_snapshot(&self, snapshot_path: String) -> thrift::Result<agent_service::TAgentResult>;
  fn handle_publish_cluster_state(&self, request: agent_service::TAgentPublishRequest) -> thrift::Result<agent_service::TAgentResult>;
  fn handle_get_tablet_stat(&self) -> thrift::Result<TTabletStatResult>;
  fn handle_get_trash_used_capacity(&self) -> thrift::Result<i64>;
  fn handle_get_disk_trash_used_capacity(&self) -> thrift::Result<Vec<TDiskTrashInfo>>;
  fn handle_submit_routine_load_task(&self, tasks: Vec<TRoutineLoadTask>) -> thrift::Result<status::TStatus>;
  fn handle_open_scanner(&self, params: doris_external_service::TScanOpenParams) -> thrift::Result<doris_external_service::TScanOpenResult>;
  fn handle_get_next(&self, params: doris_external_service::TScanNextBatchParams) -> thrift::Result<doris_external_service::TScanBatchResult>;
  fn handle_close_scanner(&self, params: doris_external_service::TScanCloseParams) -> thrift::Result<doris_external_service::TScanCloseResult>;
  fn handle_get_stream_load_record(&self, last_stream_record_time: i64) -> thrift::Result<TStreamLoadRecordResult>;
  fn handle_check_storage_format(&self) -> thrift::Result<TCheckStorageFormatResult>;
  fn handle_warm_up_cache_async(&self, request: TWarmUpCacheAsyncRequest) -> thrift::Result<TWarmUpCacheAsyncResponse>;
  fn handle_check_warm_up_cache_async(&self, request: TCheckWarmUpCacheAsyncRequest) -> thrift::Result<TCheckWarmUpCacheAsyncResponse>;
  fn handle_sync_load_for_tablets(&self, request: TSyncLoadForTabletsRequest) -> thrift::Result<TSyncLoadForTabletsResponse>;
  fn handle_get_top_n_hot_partitions(&self, request: TGetTopNHotPartitionsRequest) -> thrift::Result<TGetTopNHotPartitionsResponse>;
  fn handle_warm_up_tablets(&self, request: TWarmUpTabletsRequest) -> thrift::Result<TWarmUpTabletsResponse>;
  fn handle_ingest_binlog(&self, ingest_binlog_request: TIngestBinlogRequest) -> thrift::Result<TIngestBinlogResult>;
  fn handle_query_ingest_binlog(&self, query_ingest_binlog_request: TQueryIngestBinlogRequest) -> thrift::Result<TQueryIngestBinlogResult>;
  fn handle_publish_topic_info(&self, topic_request: TPublishTopicRequest) -> thrift::Result<TPublishTopicResult>;
  fn handle_get_realtime_exec_status(&self, request: TGetRealtimeExecStatusRequest) -> thrift::Result<TGetRealtimeExecStatusResponse>;
  fn handle_get_dictionary_status(&self, dictionary_ids: Vec<i64>) -> thrift::Result<TDictionaryStatusList>;
  fn handle_test_storage_connectivity(&self, request: TTestStorageConnectivityRequest) -> thrift::Result<TTestStorageConnectivityResponse>;
  fn handle_get_python_envs(&self) -> thrift::Result<Vec<TPythonEnvInfo>>;
  fn handle_get_python_packages(&self, python_version: String) -> thrift::Result<Vec<TPythonPackageInfo>>;
}

